export function describeOfficialMerchant(
  merchant_id: string,
  mcc_code: string,
  category: string,
  transaction_type: string
): string {
  const mccDesc = mcc_code && OFFICIAL_MCC_LABELS[mcc_code] ? OFFICIAL_MCC_LABELS[mcc_code] : category;
  return merchant_id ? merchant_id + " · " + mccDesc : category + " (" + transaction_type + ")";
}

export function parseOfficialCsvLine(line: string): SBankTransaction | null {
  if (!line) return null;
  const parts = line.split(",");
  if (parts.length < 8) return null;
  const [
    customer_id,
    bank_account_id,
    tx_date,
    tx_timestamp,
    category,
    tx_amount_eur,
    balance_after_eur,
    transaction_type,
    merchant_id = "",
    mcc_code = ""
  ] = parts;
  const trimmedMcc = mcc_code.trim();
  return {
    customer_id,
    bank_account_id,
    tx_date,
    tx_timestamp,
    category,
    tx_amount_eur: Number(tx_amount_eur),
    balance_after_eur: Number(balance_after_eur),
    transaction_type,
    merchant_id,
    mcc_code: trimmedMcc,
    merchant_label: describeOfficialMerchant(merchant_id, trimmedMcc, category, transaction_type),
    account_provider: "S-Pankki"
  };
}

