const parsedCache = new Map<string, SBankTransaction[]>();

export function getOfficialCustomerTransactions(customerId: string): SBankTransaction[] | null {
  if (parsedCache.has(customerId)) return parsedCache.get(customerId)!;
  const raw = RAW_OFFICIAL_CSV_BY_CUSTOMER[customerId];
  if (!raw) return null;
  const parsed = raw
    .split("\n")
    .map(parseOfficialCsvLine)
    .filter((t): t is SBankTransaction => t !== null);
  parsedCache.set(customerId, parsed);
  return parsed;
}
